// Writes mcp/pages/security-brief.generated.ts from connect/security-brief.md, so the Worker's /security page carries
// the brief word for word (a Worker cannot read a file, and Wrangler loads no .md without a rule in every room's config).
// Run it after any change to the brief:
//   node scripts/security-brief.ts           rewrites the generated file
//   node scripts/security-brief.ts --check   exits 1 when it has drifted from the brief
// mcp/pages/security.test.ts runs the same check under npm test. Never edit the generated file by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const BRIEF_FILE = join(import.meta.dirname, '..', 'connect', 'security-brief.md');
export const GENERATED_FILE = join(import.meta.dirname, '..', 'mcp', 'pages', 'security-brief.generated.ts');

/** The generated module for a brief: one exported string, as JSON, so every word stays readable to a pattern scan. */
export function renderBriefModule(markdown: string): string {
  return `// SPDX-License-Identifier: Apache-2.0
// Generated by scripts/security-brief.ts from connect/security-brief.md. Do not edit: change the brief, then run
// node scripts/security-brief.ts.

/** connect/security-brief.md, word for word. */
export const SECURITY_BRIEF_MD = ${JSON.stringify(markdown)};
`;
}

function main(args: string[]): number {
  const expected = renderBriefModule(readFileSync(BRIEF_FILE, 'utf8'));
  let current = '';
  try {
    current = readFileSync(GENERATED_FILE, 'utf8');
  } catch {
    // Missing: written below, or reported as drift by --check.
  }
  if (current === expected) return 0;
  if (args.includes('--check')) {
    console.error('mcp/pages/security-brief.generated.ts is out of date: run node scripts/security-brief.ts');
    return 1;
  }
  writeFileSync(GENERATED_FILE, expected);
  console.log('wrote mcp/pages/security-brief.generated.ts');
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
